StructuralRule.Predicate:
FunctionCall message:
  message.possibleTargets contains [Function systemMessage:
    systemMessage.name == "SystemMessage"
  ] and
  message.arguments[0] is [FunctionCall builderCall:
    builderCall.possibleTargets contains [Function builder:
      builder.parameters contains [Variable p:
        builder contains [ReturnStatement r:
          r.enclosingFunction === builder and
          r.expression contains [StringLiteral:] and
          r.expression contains [VariableAccess input:
            input.variable === p and input.enclosingFunction === builder
          ]
        ]
      ]
    ]
  ]
